styles:
.eco-lede { max-width: 46rem; line-height: 1.55; color: var(--is-text-soft); }
    .eco-steps { margin: 0 0 1.25rem; padding-left: 1.25rem; color: var(--is-text-soft); }
    .eco-steps li { margin: 0.35rem 0; }
    .eco-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));
      margin: 0 0 1.25rem;
    }
    .eco-pick {
      display: flex; flex-direction: column; gap: 0.45rem;
      padding: 0.75rem 0.85rem;
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius, 0.5em);
      background: var(--is-bg-elev);
      max-height: 16rem; overflow: auto;
    }
    .eco-pick label {
      display: flex; align-items: center; gap: 0.45rem;
      font-size: 0.82rem; color: var(--is-text);
      cursor: pointer;
    }
    .eco-pick code { font-size: 0.75rem; color: var(--is-text-dim); }
    .eco-bytes {
      margin: 0 0 0.75rem; font-size: 0.85rem; color: var(--is-text-soft);
    }
    .eco-bytes strong { color: var(--is-text); font-variant-numeric: tabular-nums; }
    .eco-snippet-wrap { margin: 0 0 1rem; }
    .eco-live {
      display: flex; flex-wrap: wrap; gap: 0.5rem; align-items: center;
      padding: 0.85rem; border: 1px dashed var(--is-border);
      border-radius: var(--is-radius, 0.5em); background: var(--is-bg-soft);
      min-height: 3.2rem;
    }
    .eco-toolbar {
      display: flex; flex-wrap: wrap; gap: 0.75rem 1rem;
      align-items: end; margin: 0 0 1rem;
    }
    .eco-field {
      display: flex; flex-direction: column; gap: 0.3rem;
      font-size: 0.75rem; color: var(--is-text-soft);
      min-width: min(100%, 16rem); flex: 1 1 14rem;
    }
    .eco-field input {
      font: inherit; font-size: 0.875rem; color: var(--is-text);
      background: var(--is-bg); border: 1px solid var(--is-border);
      border-radius: var(--is-radius-sm, 0.35em); padding: 0.4rem 0.55rem;
    }
    .eco-count { margin: 0 0 0.75rem; font-size: 0.8rem; color: var(--is-text-dim); }
    .eco-list { display: flex; flex-direction: column; gap: 0.65rem; }
    .eco-card {
      padding: 0.75rem 0.9rem; border: 1px solid var(--is-border);
      border-radius: var(--is-radius, 0.5em); background: var(--is-bg-elev);
    }
    .eco-card__head {
      display: flex; flex-wrap: wrap; align-items: baseline;
      gap: 0.35rem 0.75rem; margin-bottom: 0.35rem;
    }
    .eco-card__id { margin: 0; font-size: 1rem; font-weight: 650; color: var(--is-text); }
    .eco-card__path {
      font-family: ui-monospace, Menlo, Consolas, monospace;
      font-size: 0.72rem; color: var(--is-text-dim); word-break: break-all;
    }
    .eco-card__sum {
      margin: 0 0 0.45rem; font-size: 0.875rem; color: var(--is-text-soft); line-height: 1.4;
    }
    .eco-exports {
      display: flex; flex-wrap: wrap; gap: 0.3rem;
      margin: 0; padding: 0; list-style: none;
    }
    .eco-exports code {
      font-size: 0.72rem; padding: 0.1rem 0.35rem; border-radius: 0.25em;
      background: var(--is-code-bg, var(--is-bg-soft)); color: var(--is-code-text, var(--is-text));
    }
    .eco-meta { margin: 0.45rem 0 0; font-size: 0.72rem; color: var(--is-text-dim); }
